// page.mdx:82 — a program
const services = defineSource({
  id: "catalogue.services",
  description: "What this shop offers, most popular first.",
  params: z.object({
    tag: z.string().min(1).max(40),
    limit: z.number().int().min(1).max(12),
  }),
  answers: z.array(z.object({ name: z.string(), price: z.string() })),
  adapter: {
    fetch: async ({ params }) => {
      const rows = await db.services(params.tag, params.limit)

      return { ok: true, value: rows }
    },
  },
})

const built = createDataRegistry([services])

if (!built.ok) throw new Error(describeDataRegistryError(built.error))

const sources = built.value

// page.mdx:145 — a program
const data = await resolveTreeData(page, { registry: sources })

const rendered = renderLoomTree(page, { resolver: primitives, validator: primitives, data })

// page.mdx:265 — the inside of an object literal
const objectAtLine265 = {
reads: [{ fromProp: "binding", default: "entries" }],
}

// page.mdx:359 — a program
/** What this component can draw. The source promised something looser. */
const service = z.object({ name: z.string().min(1), price: z.string().min(1) })

/**
 * One reading of one answer, called by the component and by the declaration
 * below — so the count and the page cannot disagree.
 */
const readServices = (answer: DataOutcome | undefined) => {
  if (answer === undefined || answer.status === "unavailable") return undefined

  const given = z.array(z.unknown()).safeParse(answer.value)

  if (!given.success) return undefined

  const drawable = given.data.flatMap((row) => {
    const parsed = service.safeParse(row)

    return parsed.success ? [parsed.data] : []
  })

  return { given: given.data.length, drawable }
}

export const serviceList = definePrimitive({
  type: "shop.service-list",
  description: "The shop's services, read from a catalogue.services binding.",
  props: z.object({}).strict(),
  slots: ["empty", "unavailable"],
  reads: ["services"],
  unshown: (_props, data) => {
    const reading = readServices(data["services"])

    return reading === undefined
      ? []
      : [{ name: "services", given: reading.given, shown: reading.drawable.length }]
  },
  component: ({ loom }: LoomPrimitiveProps<Record<string, never>>) => {
    const reading = readServices(loom.data["services"])

    if (reading === undefined) return loom.slots["unavailable"] ?? null

    if (reading.drawable.length === 0) return loom.slots["empty"] ?? null

    return createElement(
      "ul",
      loom.editable,
      reading.drawable.map((row) =>
        createElement("li", { key: row.name }, `${row.name} — ${row.price}`)
      )
    )
  },
})

